#include <iostream>
using namespace std;

int main() {
    // Input dei dati
    int consumo_mensile;
    float importo = 0;

    cout << "Inserire consumo mensile: ";
    cin >> consumo_mensile;

    // Logica del programma
    if (consumo_mensile <= 500) {
        cout << "L'importo e' 20 euro" << endl;
    } 
    else if (consumo_mensile <= 1000) {
        importo = 20 + 0.08 * (consumo_mensile - 500);
        cout << "L'importo e': " << importo << " euro" << endl;
    } 
    else {
        importo = 60 + 0.05 * (consumo_mensile - 1000);
        cout << "L'importo e': " << importo << " euro" << endl;
    }

    system("pause");
}
